import '@kerfjs/ui/layout.css';
import { signal } from 'kerfjs';
import { EmptyState } from '@kerfjs/ui/empty-state';
import { LoadingSpinner } from '@kerfjs/ui/loading-spinner';
import { StateBanner } from '@kerfjs/ui/state-banner';

type State = 'loading' | 'empty' | 'ready' | 'refreshing' | 'error';
const savedTasks = ['Confirm keyboard order', 'Review phone layout'];
export function createReleaseTasks() {
  const state = signal<State>('loading');
  const list = () => <ul aria-label="Release tasks">{savedTasks.map(task => <li>{task}</li>)}</ul>;
  const body = () => {
    if (state.value === 'loading') return <EmptyState title="Loading release tasks" detail="Your tasks will appear here when loading completes." busy />;
    if (state.value === 'empty') return <EmptyState title="No release tasks" detail="Create the first task for this release." action={<button type="button" data-action="create">Create task</button>} />;
    if (state.value === 'error') return <StateBanner title="Release tasks could not be refreshed" detail="Your saved results and filters are still available. Try again when the connection recovers." tone="danger" urgency="alert" action={<button type="button" data-action="retry">Retry</button>} />;
    return <>{state.value === 'refreshing' && <StateBanner title="Showing saved tasks" detail="Refreshing in the background." tone="warning" action={<LoadingSpinner label="Refreshing release tasks" />} />}{list()}</>;
  };
  const render = () => <section class="release-tasks kui-layout"><header><h1>Release tasks</h1><button type="button" data-action="refresh">Refresh</button></header><div class="release-tasks__body kui-pane-body kui-scroll-owner" aria-live="polite">{body()}</div></section>;
  return { render, action(command: string) { const next: Record<string, State> = { complete: 'ready', clear: 'empty', create: 'ready', refresh: 'refreshing', finish: 'ready', fail: 'error', retry: 'refreshing' }; if (next[command]) state.value = next[command]; } };
}
